{"type":"SearchReplace","EditsApplied":{"old_string":"","new_string":"/**
 * Persistence for bulk issue import: the idempotency row plus the issue and
 * label writes that belong to one upload. The write path is one transaction
 * so a failed import leaves neither issues nor a spent key.
 */
import { and, eq, inArray, sql } from "drizzle-orm";
import { newId } from "@/lib/id";
import {
  getDb,
  issueImports,
  issueLabels,
  issues,
  labels,
  members,
  users,
} from "@/server/db";
import { toIsoTimestamp } from "@/types/common";
import { livePredicate, orgPredicate } from "./base-repository";
import { compact } from "./_paging";
import { brandId, parseJsonArray, toIssue } from "./_mappers";
import type { ImportIssueRowInput } from "@/schemas/issue-import";
import type { IssueId, LabelId, OrgId, ProjectId, UserId } from "@/types/common";
import type { Issue } from "@/types/issue";

/** Colour applied when an import creates a label that does not exist yet. */
const DEFAULT_LABEL_COLOR = "#94a3b8";

export type StoredIssueImport = {
  readonly projectId: ProjectId;
  readonly issueIds: readonly IssueId[];
};

export async function findIssueImport(
  orgId: OrgId,
  importKey: string,
): Promise<StoredIssueImport | null> {
  const row = getDb()
    .select()
    .from(issueImports)
    .where(
      and(
        orgPredicate(issueImports.orgId, orgId),
        eq(issueImports.importKey, importKey),
      ),
    )
    .get();

  if (!row) return null;

  return {
    projectId: brandId<ProjectId>(row.projectId),
    issueIds: parseJsonArray<string>(row.issueIds).map((id) =>
      brandId<IssueId>(id),
    ),
  };
}

/** Loads previously imported issues in the stored file order, including archived ones. */
export async function loadIssuesInOrder(
  orgId: OrgId,
  issueIds: readonly IssueId[],
): Promise<Issue[]> {
  if (issueIds.length === 0) return [];

  const db = getDb();
  const rows = db
    .select()
    .from(issues)
    .where(
      and(
        orgPredicate(issues.orgId, orgId),
        inArray(issues.id, [...issueIds]),
      ),
    )
    .all();

  const labelRows = db
    .select({
      issueId: issueLabels.issueId,
      labelId: issueLabels.labelId,
    })
    .from(issueLabels)
    .where(
      and(
        orgPredicate(issueLabels.orgId, orgId),
        inArray(issueLabels.issueId, [...issueIds]),
      ),
    )
    .orderBy(sql`rowid`)
    .all();

  const labelsByIssue = new Map<string, LabelId[]>();
  for (const labelRow of labelRows) {
    const list = labelsByIssue.get(labelRow.issueId) ?? [];
    list.push(brandId<LabelId>(labelRow.labelId));
    labelsByIssue.set(labelRow.issueId, list);
  }

  const byId = new Map(rows.map((row) => [row.id, row]));

  return issueIds.map((issueId) => {
    const row = byId.get(issueId);
    if (!row) throw new Error(`Imported issue ${issueId} is missing`);
    return toIssue(row, labelsByIssue.get(issueId) ?? []);
  });
}

/**
 * Creates any missing labels, the issues in file order, and the import row.
 * Synchronous inside the SQLite transaction so a throw rolls every write back.
 */
export async function commitIssueImport(input: {
  orgId: OrgId;
  projectId: ProjectId;
  importKey: string;
  authorId: UserId;
  rows: readonly ImportIssueRowInput[];
}): Promise<Issue[]> {
  const db = getDb();

  return db.transaction((tx) => {
    const memberRows = tx
      .select({ userId: users.id, email: users.email })
      .from(members)
      .innerJoin(users, eq(users.id, members.userId))
      .where(
        and(
          ...compact(
            orgPredicate(members.orgId, input.orgId),
            eq(members.status, "active"),
            livePredicate(members.archivedAt, {}),
          ),
        ),
      )
      .all();

    const assigneeByEmail = new Map<string, UserId>();
    for (const member of memberRows) {
      assigneeByEmail.set(member.email.toLowerCase(), brandId<UserId>(member.userId));
    }

    const labelRows = tx
      .select({ id: labels.id, name: labels.name })
      .from(labels)
      .where(orgPredicate(labels.orgId, input.orgId))
      .all();

    const labelIdByName = new Map<string, LabelId>();
    for (const label of labelRows) {
      labelIdByName.set(label.name, brandId<LabelId>(label.id));
    }

    const missingNames: string[] = [];
    const seenNames = new Set<string>();
    for (const row of input.rows) {
      for (const name of row.labels) {
        if (seenNames.has(name)) continue;
        seenNames.add(name);
        if (!labelIdByName.has(name)) missingNames.push(name);
      }
    }

    const stamp = toIsoTimestamp(new Date());
    for (const name of missingNames) {
      const id = newId();
      tx.insert(labels)
        .values({
          id,
          orgId: input.orgId,
          name,
          color: DEFAULT_LABEL_COLOR,
          description: null,
          createdAt: stamp,
          updatedAt: stamp,
        })
        .run();
      labelIdByName.set(name, brandId<LabelId>(id));
    }

    const maxRow = tx
      .select({ value: sql<number | null>`max(${issues.number})` })
      .from(issues)
      .where(
        and(
          orgPredicate(issues.orgId, input.orgId),
          eq(issues.projectId, input.projectId),
        ),
      )
      .get();

    let number = (maxRow?.value ?? 0) + 1;
    const created: Issue[] = [];

    for (const row of input.rows) {
      const labelIds = uniqueLabelIds(row.labels, labelIdByName);
      const assigneeId =
        row.assigneeEmail === null
          ? null
          : (assigneeByEmail.get(row.assigneeEmail.toLowerCase()) ?? null);

      const inserted = tx
        .insert(issues)
        .values({
          id: newId(),
          orgId: input.orgId,
          projectId: input.projectId,
          number,
          title: row.title,
          description: row.description,
          status: row.status,
          priority: row.priority,
          authorId: input.authorId,
          assigneeId,
          parentId: null,
          estimate: null,
          dueAt: row.dueAt,
          startedAt: null,
          completedAt: null,
          createdAt: stamp,
          updatedAt: stamp,
        })
        .returning()
        .get();

      if (labelIds.length > 0) {
        tx.insert(issueLabels)
          .values(
            labelIds.map((labelId) => ({
              orgId: input.orgId,
              issueId: inserted.id,
              labelId,
            })),
          )
          .run();
      }

      created.push(toIssue(inserted, labelIds));
      number += 1;
    }

    tx.insert(issueImports)
      .values({
        id: newId(),
        orgId: input.orgId,
        projectId: input.projectId,
        importKey: input.importKey,
        issueIds: JSON.stringify(created.map((issue) => issue.id)),
        createdAt: stamp,
      })
      .run();

    return created;
  });
}

function uniqueLabelIds(
  names: readonly string[],
  labelIdByName: ReadonlyMap<string, LabelId>,
): LabelId[] {
  const ids: LabelId[] = [];
  const seen = new Set<string>();
  for (const name of names) {
    if (seen.has(name)) continue;
    seen.add(name);
    const id = labelIdByName.get(name);
    if (id === undefined) throw new Error(`Label "${name}" was not created`);
    ids.push(id);
  }
  return ids;
}
