/**
 * Turns every row of one upload into an issue. Checks tenant, permission,
 * project state, the per-project quota and the issue-creation rate allowance
 * before writing. A key this workspace already imported returns that first
 * result and writes nothing.
 */
export async function importIssues(
  actor: Actor,
  input: ImportIssuesInput,
): Promise<IssueImportResult> {
  assertOrgScope(actor, input.orgId);

  const project = requireFound(
    await projectRepo.findProjectById(input.orgId, input.projectId),
    "Project",
    input.projectId,
  );
  assertNotArchived("Project", project.id, project);
  assertCan(actor, "issue:create", projectResource(project));

  const prior = await issueImportRepo.findIssueImport(
    input.orgId,
    input.importKey,
  );
  if (prior) {
    return {
      importKey: input.importKey,
      projectId: prior.projectId,
      issues: await issueImportRepo.loadIssuesInOrder(
        input.orgId,
        prior.issueIds,
      ),
      replayed: true,
    };
  }

  const org = requireFound(
    await orgRepo.findOrgById(input.orgId),
    "Organization",
    input.orgId,
  );
  const used = await issueRepo.countIssues(input.orgId, input.projectId);
  if (
    wouldExceedLimit(org.plan, "issuesPerProject", used, input.rows.length)
  ) {
    throw new Error(
      `Plan ${org.plan} allows no more issues in project ${project.key}`,
    );
  }

  setOrgPlan(input.orgId, org.plan);
  const verdict = await consumeRateLimit(
    input.orgId,
    ISSUE_CREATE_BUCKET,
    input.rows.length,
  );
  if (!verdict.allowed) {
    throw new Error(
      `Issue creation rate limit reached; try again after ${verdict.resetAt}`,
    );
  }

  const issues = await issueImportRepo.commitIssueImport({
    orgId: input.orgId,
    projectId: input.projectId,
    importKey: input.importKey,
    authorId: actor.userId,
    rows: input.rows,
  });

  await emit("issues.imported", {
    ...actorEnvelope(actor),
    projectId: project.id,
    importKey: input.importKey,
    issueIds: issues.map((issue) => issue.id),
  });

  return {
    importKey: input.importKey,
    projectId: project.id,
    issues,
    replayed: false,
  };
}

