import { afterAll, beforeAll, describe, expect, it } from "vitest";
import { consumeRateLimit, resetRateLimits } from "@/lib/rate-limit";
import { AlreadyArchivedError } from "@/lib/soft-delete";
import { TenantScopeError } from "@/lib/tenant";
import { PermissionDeniedError } from "@/lib/permissions";
import { importIssuesSchema } from "@/schemas/issue-import";
import * as activityRepo from "@/server/repositories/activity-repository";
import * as issueRepo from "@/server/repositories/issue-repository";
import * as labelRepo from "@/server/repositories/label-repository";
import * as memberRepo from "@/server/repositories/member-repository";
import * as notificationRepo from "@/server/repositories/notification-repository";
import * as projectRepo from "@/server/repositories/project-repository";
import * as searchRepo from "@/server/repositories/search-repository";
import * as usageRepo from "@/server/repositories/usage-repository";
import * as userRepo from "@/server/repositories/user-repository";
import * as webhookRepo from "@/server/repositories/webhook-repository";
import { NotFoundError } from "@/server/services/_support";
import {
  registerEventHandlers,
  unregisterEventHandlers,
} from "@/server/services/event-registry";
import * as issueService from "@/server/services/issue-service";
import * as projectService from "@/server/services/project-service";
import { createTenant, useTemporaryDatabase } from "../server/_support/fixtures";
import type { Tenant } from "../server/_support/fixtures";

let cleanup: () => void;
let tenant: Tenant;
let other: Tenant;

beforeAll(async () => {
  cleanup = await useTemporaryDatabase();
  tenant = await createTenant("import", "growth");
  other = await createTenant("other", "growth");
  registerEventHandlers();
});

afterAll(() => {
  unregisterEventHandlers();
  cleanup();
});

describe("importIssues", () => {
  it("creates issues in order and replays", async () => {
    resetRateLimits();
    const parsed = importIssuesSchema.parse({
      orgId: tenant.org.id,
      projectId: tenant.project.id,
      importKey: "upload-001",
      rows: [
        {
          title: "First row",
          assigneeEmail: "ADMIN@import.test",
          labels: ["Bug", "Bug", "New"],
          status: "todo",
          priority: "high",
          dueAt: "2026-05-01T00:00:00.000Z",
          description: "alpha",
        },
        {
          title: "Second row",
          labels: ["New", "bug"],
          assigneeEmail: "missing@nope.test",
        },
      ],
    });

    const created = await issueService.importIssues(tenant.actors.member, parsed);
    expect(created.replayed).toBe(false);
    expect(created.issues.map((issue) => issue.number)).toEqual([1, 2]);
    expect(created.issues[0]).toMatchObject({
      title: "First row",
      description: "alpha",
      status: "todo",
      priority: "high",
      dueAt: "2026-05-01T00:00:00.000Z",
      authorId: tenant.userIds.member,
      assigneeId: tenant.userIds.admin,
      parentId: null,
      estimate: null,
    });
    expect(created.issues[1]).toMatchObject({
      title: "Second row",
      assigneeId: null,
      status: "backlog",
      priority: "none",
      description: null,
    });

    const labels = await labelRepo.listLabels(tenant.org.id);
    const byName = new Map(labels.map((label) => [label.name, label]));
    expect(byName.get("Bug")?.color).toBe("#94a3b8");
    expect(byName.get("Bug")?.description).toBeNull();
    expect(byName.get("bug")?.color).toBe("#94a3b8");
    expect(created.issues[0]?.labelIds).toEqual([
      byName.get("Bug")?.id,
      byName.get("New")?.id,
    ]);
    expect(created.issues[1]?.labelIds).toEqual([
      byName.get("New")?.id,
      byName.get("bug")?.id,
    ]);

    const replay = await issueService.importIssues(tenant.actors.member, {
      ...parsed,
      rows: [{ title: "Ignored row", labels: ["Nope"] }],
    });
    expect(replay.replayed).toBe(true);
    expect(replay.issues.map((issue) => issue.id)).toEqual(
      created.issues.map((issue) => issue.id),
    );
    expect(await labelRepo.listLabels(tenant.org.id)).toHaveLength(labels.length);

    const next = await issueService.createIssue(tenant.actors.member, {
      orgId: tenant.org.id,
      projectId: tenant.project.id,
      title: "After import",
      description: null,
      status: "backlog",
      priority: "none",
      assigneeId: null,
      parentId: null,
      estimate: null,
      dueAt: null,
      labelIds: [],
    });
    expect(next.number).toBe(3);

    const activity = await activityRepo.listActivity({
      orgId: tenant.org.id,
      limit: 50,
      cursor: null,
    });
    const imported = activity.items.filter((event) => event.action === "issues.imported");
    expect(imported).toHaveLength(1);
    expect(imported[0]).toMatchObject({
      actorId: tenant.userIds.member,
      subjectKind: "project",
      subjectId: tenant.project.id,
      projectId: tenant.project.id,
      metadata: { count: 2, importKey: "upload-001" },
    });
    expect(
      activity.items.filter((event) => event.action === "issue.created"),
    ).toHaveLength(1);

    const usage = await usageRepo.getUsage(tenant.org.id);
    const recounted = await usageRepo.recomputeUsage(tenant.org.id);
    expect(usage.issuesUsed).toBe(3);
    expect(recounted.issuesUsed).toBe(3);

    const hits = await searchRepo.searchDocuments({
      orgId: tenant.org.id,
      q: "alpha",
      limit: 10,
      cursor: null,
    });
    expect(hits.items.some((hit) => hit.subjectId === created.issues[0]?.id)).toBe(
      true,
    );

    const notes = await notificationRepo.listNotifications({
      orgId: tenant.org.id,
      recipientId: tenant.userIds.admin,
      limit: 20,
      cursor: null,
    });
    expect(notes.items).toHaveLength(0);

    expect(await webhookRepo.claimPendingDeliveries(20)).toHaveLength(0);
  });

  it("refuses over quota and over rate without spending the key", async () => {
    resetRateLimits();
    const free = await createTenant("freeorg", "free");
    for (let i = 0; i < 99; i += 1) {
      await issueRepo.insertIssue(
        {
          orgId: free.org.id,
          projectId: free.project.id,
          title: `Seed ${i} xx`,
          description: null,
          status: "backlog",
          priority: "none",
          assigneeId: null,
          parentId: null,
          estimate: null,
          dueAt: null,
          labelIds: [],
        },
        free.userIds.member,
        i + 1,
      );
    }

    await expect(
      issueService.importIssues(free.actors.member, {
        orgId: free.org.id,
        projectId: free.project.id,
        importKey: "quota-key1",
        rows: [
          { title: "Over one", description: null, status: "backlog", priority: "none", assigneeEmail: null, labels: [], dueAt: null },
          { title: "Over two", description: null, status: "backlog", priority: "none", assigneeEmail: null, labels: [], dueAt: null },
        ],
      }),
    ).rejects.toThrow(
      `Plan free allows no more issues in project ${free.project.key}`,
    );
    expect(await issueRepo.countIssues(free.org.id, free.project.id)).toBe(99);

    const later = await issueService.importIssues(free.actors.member, {
      orgId: free.org.id,
      projectId: free.project.id,
      importKey: "quota-key1",
      rows: [
        {
          title: "Fits now",
          description: null,
          status: "backlog",
          priority: "none",
          assigneeEmail: null,
          labels: [],
          dueAt: null,
        },
      ],
    });
    expect(later.replayed).toBe(false);
    expect(later.issues[0]?.number).toBe(100);

    resetRateLimits();
    const rows = Array.from({ length: 61 }, (_, i) => ({
      title: `Rate ${i} row`,
      description: null,
      status: "backlog" as const,
      priority: "none" as const,
      assigneeEmail: null,
      labels: [] as string[],
      dueAt: null,
    }));
    await expect(
      issueService.importIssues(free.actors.member, {
        orgId: free.org.id,
        projectId: free.project.id,
        importKey: "rate-key01",
        rows,
      }),
    ).rejects.toThrow(/rate limit/);
    expect(await issueRepo.countIssues(free.org.id, free.project.id)).toBe(100);

    const verdict = await consumeRateLimit(free.org.id, "issue:create", 1);
    expect(verdict.allowed).toBe(true);

    const first = await issueService.importIssues(free.actors.member, {
      orgId: free.org.id,
      projectId: free.project.id,
      importKey: "rate-key01",
      rows: [rows[0]!],
    });
    expect(first.replayed).toBe(false);
  });

  it("enforces access and keeps keys per workspace", async () => {
    await expect(
      issueService.importIssues(other.actors.member, {
        orgId: tenant.org.id,
        projectId: tenant.project.id,
        importKey: "upload-001",
        rows: [
          {
            title: "Cross tenant",
            description: null,
            status: "backlog",
            priority: "none",
            assigneeEmail: null,
            labels: [],
            dueAt: null,
          },
        ],
      }),
    ).rejects.toBeInstanceOf(TenantScopeError);

    await expect(
      issueService.importIssues(tenant.actors.viewer, {
        orgId: tenant.org.id,
        projectId: tenant.project.id,
        importKey: "viewer-key1",
        rows: [
          {
            title: "Viewer nope",
            description: null,
            status: "backlog",
            priority: "none",
            assigneeEmail: null,
            labels: [],
            dueAt: null,
          },
        ],
      }),
    ).rejects.toBeInstanceOf(PermissionDeniedError);

    await expect(
      issueService.importIssues(tenant.actors.member, {
        orgId: tenant.org.id,
        projectId: other.project.id,
        importKey: "missing-proj",
        rows: [
          {
            title: "Unknown proj",
            description: null,
            status: "backlog",
            priority: "none",
            assigneeEmail: null,
            labels: [],
            dueAt: null,
          },
        ],
      }),
    ).rejects.toBeInstanceOf(NotFoundError);

    await projectService.archiveProject(tenant.actors.admin, {
      orgId: tenant.org.id,
      projectId: tenant.project.id,
    });
    await expect(
      issueService.importIssues(tenant.actors.member, {
        orgId: tenant.org.id,
        projectId: tenant.project.id,
        importKey: "upload-001",
        rows: [
          {
            title: "Archived proj",
            description: null,
            status: "backlog",
            priority: "none",
            assigneeEmail: null,
            labels: [],
            dueAt: null,
          },
        ],
      }),
    ).rejects.toBeInstanceOf(AlreadyArchivedError);

    const removed = await userRepo.insertUser({
      email: "gone@import.test",
      name: "Gone",
      passwordHash: "seed",
    });
    const membership = await memberRepo.insertMember(
      other.org.id,
      removed.id,
      "member",
      null,
    );
    await memberRepo.archiveMember(other.org.id, membership.id);

    resetRateLimits();
    const fresh = await projectRepo.insertProject({
      orgId: other.org.id,
      name: "Other board",
      slug: "board",
      key: "BRD",
      description: null,
      visibility: "org",
      leadId: other.userIds.owner,
      color: "#6366f1",
      targetDate: null,
    });
    const result = await issueService.importIssues(other.actors.member, {
      orgId: other.org.id,
      projectId: fresh.id,
      importKey: "upload-001",
      rows: [
        {
          title: "Same key elsewhere",
          description: null,
          status: "in_progress",
          priority: "low",
          assigneeEmail: "gone@import.test",
          labels: ["Bug"],
          dueAt: null,
        },
      ],
    });
    expect(result.replayed).toBe(false);
    expect(result.projectId).toBe(fresh.id);
    expect(result.issues[0]?.assigneeId).toBeNull();
    expect(result.issues[0]?.number).toBe(1);
    const otherLabels = await labelRepo.listLabels(other.org.id);
    expect(otherLabels.map((label) => label.name)).toContain("Bug");
    expect(otherLabels).toHaveLength(1);
  });
});

